"""Blender clip export (JSON, nd_io.export) -> src/Client/AuthoredClips.luau.
Usage: python3 clips_to_luau.py out.luau clips_a.json [clips_b.json ...]"""
import json, sys

def fmt(v):
    s = ("%.4f" % v).rstrip("0").rstrip(".")
    return "0" if s in ("-0", "") else s

def main(out, inputs):
    clips = {}
    for p in inputs:
        clips.update(json.load(open(p)))
    lines = ["-- GENERATED by tools/blender/clips_to_luau.py from the Blender pipeline",
             "-- (tools/blender, Documents/NinjaDuelBlender). Do not edit by hand:",
             "-- re-author in Blender and re-export. Rows: Root = x,y,z,qx,qy,qz,qw;",
             "-- other joints = qx,qy,qz,qw; Roblox axes (Motor6D.Transform).",
             "return {"]
    for name in sorted(clips):
        c = clips[name]
        markers = ",".join("%s=%s" % (k, fmt(v)) for k, v in sorted(c["markers"].items()))
        lines.append('\t["%s"]={fps=%d,frames=%d,length=%s,loop=%s,markers={%s},joints={' % (
            name, c["fps"], c["frames"], fmt(c["length"]), "true" if c["loop"] else "false", markers))
        for joint, rows in c["joints"].items():
            flat = ",".join(fmt(v) for row in rows for v in row)
            lines.append("\t\t%s={%s}," % (joint, flat))
        lines.append("\t}},")
    lines.append("}")
    open(out, "w").write("\n".join(lines) + "\n")
    print(out, len(clips), "clips")

if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2:])
